"use client"

import { useRef } from "react"

import { AnimatedBeam } from "@/components/ui/animated-beam"

export function Integration() {
  const containerRef = useRef<HTMLDivElement>(null)
  const fromRef = useRef<HTMLDivElement>(null)
  const toRef = useRef<HTMLDivElement>(null)

  return (
    <div ref={containerRef} className="relative flex w-full max-w-md justify-between p-10">
      <div ref={fromRef} className="z-10 size-12 rounded-full border-2 bg-white" />
      <div ref={toRef} className="z-10 size-12 rounded-full border-2 bg-white" />
      <AnimatedBeam containerRef={containerRef} fromRef={fromRef} toRef={toRef} />
    </div>
  )
}
